// Zet het jobbestand op 'fout' als de workflow onderweg afbreekt.
//
// Waarom dit bestaat: alleen de nodes halverwege en aan het eind schrijven een
// status in het jobbestand. Breekt de workflow daarvóór af — bijvoorbeeld omdat
// de bankopdracht niet herkend werd of Docling niet antwoordde — dan blijft de
// status op 'documenten omzetten' staan. De webapp blijft dan pollen op een run
// die nooit meer iets doet: geen foutmelding, alleen een oneindige wachtstand.
//
// Koppeling job <-> executie: elk jobId eindigt op het n8n-executienummer
// (`akte_20260901_111014_3265` hoort bij executie 3265). Zo vinden we het
// bestand terug zonder dat de falende workflow iets hoeft door te geven.
const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';

const uitvoering = $json.execution || {};
const workflow = $json.workflow || {};
const executieId = String(uitvoering.id || '').trim();
// n8n knipt een lange fout uit een Code-node in tweeën: het begin belandt in
// 'description' en de staart in 'message'. Aan één van de twee heb je niets, dus
// plakken we ze weer aan elkaar wanneer ze elkaar aanvullen.
const fout = uitvoering.error || {};
const delen = [fout.description, fout.message]
  .map((x) => String(x == null ? '' : x).trim())
  .filter(Boolean);
const uniek = delen.filter((d, i) => !delen.some((ander, j) => j < i && ander.includes(d)));
const melding = (uniek.join(' ') || 'Onbekende fout').slice(0, 600);
const node = uitvoering.lastNodeExecuted || '';

if (!executieId) {
  return [{ json: { bijgewerkt: false, reden: 'geen executie-id in de foutmelding' } }];
}

let bestanden = [];
try {
  bestanden = fs.readdirSync(JOB_DIR).filter((n) => n.endsWith(`_${executieId}.json`));
} catch (err) {
  return [{ json: { bijgewerkt: false, reden: `jobmap onleesbaar: ${err.message}` } }];
}

if (!bestanden.length) {
  // Niet elke workflow werkt met een jobbestand (denk aan de status-poll zelf);
  // dan valt er ook niets te markeren.
  return [{ json: { bijgewerkt: false, reden: `geen jobbestand voor executie ${executieId}` } }];
}

const bijgewerkt = [];
for (const naam of bestanden) {
  const pad = `${JOB_DIR}/${naam}`;
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(pad, 'utf8'));
  } catch (_) {
    // Bestand weg of stuk: dan schrijven we het opnieuw aan met wat we weten.
  }
  // Een node die zelf al een nette melding heeft weggeschreven weet beter wat
  // er misging dan de generieke n8n-fout; die laten we staan.
  const bestaandeFout = job.fout ? String(job.fout) : '';
  const nieuw = {
    ...job,
    job_id: job.job_id || naam.replace(/\.json$/, ''),
    status: 'fout',
    fout: bestaandeFout || (node ? `${melding} (node: ${node})` : melding),
    mislukt_in_node: node || null,
    bijgewerkt_op: new Date().toISOString(),
  };
  try {
    fs.writeFileSync(pad, JSON.stringify(nieuw), 'utf8');
    bijgewerkt.push(naam);
  } catch (err) {
    return [{ json: { bijgewerkt: false, reden: `schrijven mislukt: ${err.message}` } }];
  }
}

console.error(
  `[Foutafhandeling] workflow "${workflow.name || '?'}" executie ${executieId} afgebroken in ` +
    `node "${node}": ${melding}`
);

return [{ json: { bijgewerkt: true, bestanden: bijgewerkt, executieId, node, melding } }];
